import "./refer.css";
import React, { useState } from "react";
import {
  copyIcon,
  faceBookIcon,
  linkedInIcon,
  tickIcon,
  twitterIcon,
} from "../../../../components/expansion/Svg";
import Label from "../../../../components/Modules/Label";
import { PrimaryButton } from "../../../../components/Modules/PrimaryButton";
import QuestLabs from "../../../../components/QuestLabs";
import ReferEarnThemeManager from "./referEarnThemeManager";
import { QuestThemeData } from "../../Survey/modular/types";
import { Facebook, LinkedIn, Twitter } from "./SVG";
import { extractGradientColors } from "../../../../general";

interface OfflineReferEarnProps {
  referralCode: string;
  heading?: string;
  description?: string;
  referralLink?: string;
  shareButtonText?: string;
  secondaryIconColor?: string;
  gradientBackground?: boolean;
  primaryHeading?: string;
  primaryDescription?: string;
  onCopy?: (referralCode: string) => void;
  showReferralCode?: boolean;
  showFooter?: boolean;
  gradientBackgroundColor?: string;
  styleConfig?: any;
  footerLink?: string;
  brandTheme?: any;
  QuestThemeData?: QuestThemeData;
  showReferralLogo?: boolean;
  themeConfig?: any;
}

