export const OfflineReferEarnWrapper: React.FC<OfflineReferEarnProps> = ({
  referralCode,
  heading = "Referral link and code",
  description = "Share your unique referral code with friends and receive 10 coins in credits each time a friend signs up!",
  referralLink = "",
  shareButtonText = "Copy Referral Link",
  secondaryIconColor = "#939393",
  gradientBackground = false,
  primaryHeading = "Refer and earn!",
  primaryDescription = "Welcome back, Please complete your details",
  onCopy = (referralCode: string) => {},
  showReferralCode = true,
  showFooter = true,
  gradientBackgroundColor,
  styleConfig,
  footerLink,
  brandTheme,
  QuestThemeData,
  showReferralLogo = true,
  themeConfig,
}) => {
  const [copy, setCopy] = useState<boolean[]>([false, false]);

  const themeManager = React.useMemo(
    () =>
      new ReferEarnThemeManager(
        themeConfig,
        styleConfig,
        QuestThemeData,
        brandTheme
      ),
    [themeConfig, styleConfig, QuestThemeData, brandTheme]
  );

  const handleCopy = (index: number) => {
    const textToCopy = !index ? referralCode : referralLink + referralCode;
    navigator?.clipboard.writeText(textToCopy);

    setCopy((prev) => prev.map((e, i) => (i === index ? true : e)));
    setTimeout(() => {
      setCopy((prev) => prev.map((e, i) => (i === index ? false : e)));
    }, 3000);

    onCopy(textToCopy);
  };

  const handleSocialShare = (platform: "linkedin" | "facebook" | "x") => {
    const shareUrl = referralLink + referralCode;
    const urls = {
      linkedin: `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(shareUrl)}`,
      facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}`,
      x: `https://twitter.com/intent/tweet?url=${encodeURIComponent(shareUrl)}`,
    };
    window.open(urls[platform], '_blank');
  };

  const renderReferralCodeSection = () => (
    <div className="q_refer_code_content">
      <Label children="Referral Code" style={themeManager.getLabelStyles()} />
      <div
        className="q_refer_code_box"
        style={themeManager.getReferralCodeStyles().container}
      >
        <div
          className="q_refer_code"
          style={themeManager.getReferralCodeStyles().text}
        >
          {referralCode}
        </div>
        <img
          className="q_refer_copy_icon"
          src={
            copy[0]
              ? tickIcon(styleConfig?.Icon?.color)
              : copyIcon(secondaryIconColor)
          }
          onClick={() => handleCopy(0)}
          alt=""
          style={{...themeManager.getIconStyles(),background:"none"}}
        />
      </div>
    </div>
  );

  const renderReferralLinkSection = () => (
    <div className="q_refer_code_content">
      <Label children="Invitation Link" style={themeManager.getLabelStyles()} />
      <div
        className="q_refer_code_box"
        style={themeManager.getReferralCodeStyles().container}
      >
        <div
          className="q_refer_code"
          style={themeManager.getReferralCodeStyles().text}
        >
          {referralLink}
          {referralCode}
        </div>
        <img
          className="q_refer_copy_icon"
          src={
            copy[1]
              ? tickIcon(styleConfig?.Icon?.color)
              : copyIcon(secondaryIconColor)
          }
          onClick={() => handleCopy(1)}
          alt=""
          style={{ ...themeManager.getIconStyles(), background: "none" }}
        />
      </div>
    </div>
  );

  const renderSocialLinks = () => (
    <div className="q_social_links">
      <div
        className="q_social_link_icon"
        style={themeManager.getIconStyles()}
        onClick={() => handleSocialShare("linkedin")}
      >
        <LinkedIn color={extractGradientColors(styleConfig?.Icon?.color || brandTheme?.primaryColor || QuestThemeData?.accentColor || '#0065FF')} />
      </div>
      <div
        className="q_social_link_icon"
        style={themeManager.getIconStyles()}
        onClick={() => handleSocialShare("facebook")}
      >
        <Facebook color={extractGradientColors(styleConfig?.Icon?.color || brandTheme?.primaryColor || QuestThemeData?.accentColor || '#0065FF')} />
      </div>
      <div
        className="q_social_link_icon"
        style={themeManager.getIconStyles()}
        onClick={() => handleSocialShare("x")}
      >
        <Twitter color={extractGradientColors(styleConfig?.Icon?.color || brandTheme?.primaryColor || QuestThemeData?.accentColor || '#0065FF')} />
      </div>
    </div>
  );

  const renderMainContent = () => (
    <div
      className="q_refer_and_earn"
      style={themeManager.getMainContentStyles()}
    >
      {showReferralLogo && (
        <div className="q_refer_head">
          <ReferIcon primary={themeManager.getReferIconColors().primary} secondary={themeManager.getReferIconColors().secondary} />
        </div>
      )}

      <div className="q_refer_content">
        <div className="refer_content_box">
          <div
            className="q_refer_heading"
            style={themeManager.getHeadingStyles()}
          >
            {heading}
          </div>
          <div
            className="q_refer_desc"
            style={themeManager.getDescriptionStyles()}
          >
            {description}
          </div>
        </div>

        {showReferralCode && renderReferralCodeSection()}
        {referralLink && renderReferralLinkSection()}

        <PrimaryButton
          children={shareButtonText}
          style={themeManager.getPrimaryButtonStyles()}
          onClick={() => handleCopy(1)}
          type="button"
        />

        {renderSocialLinks()}
      </div>

      {!gradientBackground && showFooter && (
        <QuestLabs
          style={themeManager.getFooterStyles().container}
          textStyle={themeManager.getFooterStyles().text}
          iconStyle={themeManager.getFooterStyles().icon}
          text={themeManager.getFooterStyles().content.text}
          link={footerLink}
        />
      )}
    </div>
  );

  if (gradientBackground) {
    return (
      <div style={themeManager.getGradientWrapperStyles()}>
        <div
          className="q_gradient_background"
          style={themeManager.getGradientContainerStyles(gradientBackgroundColor)}
        >
          <div className="q_gradient_head">
            <div
              className="q_gradient_heading"
              style={themeManager.getGradientHeadingStyles()}
            >
              {primaryHeading}
            </div>
            <div
              className="q_gradient_description"
              style={themeManager.getGradientDescriptionStyles()}
            >
              {primaryDescription}
            </div>
          </div>
          {renderMainContent()}
          <div className="q_gradient_quest_powered">
            {showFooter && (
              <QuestLabs
                style={themeManager.getFooterStyles().container}
                textStyle={themeManager.getFooterStyles().text}
                iconStyle={themeManager.getFooterStyles().icon}
                text={themeManager.getFooterStyles().content.text}
                link={footerLink}
              />
            )}
          </div>
        </div>
      </div>
    );
  }

  return renderMainContent();
};

export default OfflineReferEarnWrapper;