            {/* help button  */}
            {/* <div
              className={"helhubIconCont"}
              onClick={() => {
                setHelpHub((prev) => !prev);
                isActive && isActive(!helpHub);
              }}
              style={{
                background:
                  styleConfig?.QuestLogo?.QuestLogoBackground ||
                  QuestThemeData?.accentColor,
                boxShadow: `-1px -1px 50.3px -1px rgba(${Q}, 0.75)`,
              }}
            >
              <img
                src={addIcon}
                className={`helphub-open-addIcon ${helpHub ? "show-icon" : ""}`}
              />

              {renderLogo()}
            </div> */}
            {/* {
              helphubPosition == "USER_CHOICE" && (
                // <div className="helphub-open-resizeIcon" onClick={() => setPositionInLocal(position == "POPUP" ? "SIDEBAR" : "POPUP")}>
                <img
                  src={position == "POPUP" ? resize2 : resize}
                  alt=""
                  className="helphub-open-resizeIcon"
                  style={{
                    background:
                      styleConfig?.QuestLogo?.QuestLogoBackground ||
                      QuestThemeData?.accentColor,
                  }}
                  onClick={() =>
                    setPositionInLocal(position == "POPUP" ? "SIDEBAR" : "POPUP")
                  }
                />
              )
              // </div>
            } */}

            {!!defaultAutoPopupMessagesApi.length ? (
              <div
                className={`helpHubMainCont-default-popup ${
                  autoPopupMessage
                    ? "helpHubMainCont-default-popup-animated"
                    : ""
                }`}
              >
                <div
                  className="home-back-btn"
                  onClick={() => setAutoPopupMessage(false)}
                >
                  {/* <img src={arrow_forward} alt="" onClick={() => setAutoPopupMessage(false)}/> */}
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="20"
                    height="20"
                    viewBox="0 0 20 20"
                    fill="none"
                  >
                    <path
                      d="M5.63184 14.3697L10.001 10.0005L14.3702 14.3697M14.3702 5.63135L10.0002 10.0005L5.63184 5.63135"
                      stroke="#696969"
                      stroke-width="1.5"
                      stroke-linecap="round"
                      stroke-linejoin="round"
                    />
                  </svg>
                </div>
                <div className="home-assistant-msg">
                  <img
                    style={{
                      background:
                        styleConfig?.QuestLogo?.QuestLogoBackground ||
                        QuestThemeData.accentColor,
                    }}
                    src={entityLogoApi || entityImage}
                    alt=""
                  />
                  <p>Hello there👋, How can I help you?</p>
                </div>
                <div className="home-user-msg">
                  {defaultAutoPopupMessagesApi.map((ele, index) => {
                    return (
                      <p
                        style={{
                          background:
                            styleConfig?.QuestLogo?.QuestContent?.background ||
                            QuestThemeData.accentColor,
                          color:
                            styleConfig?.QuestLogo?.QuestContent?.color ||
                            BrandTheme?.contentColor,
                          ...styleConfig?.QuestLogo?.QuestContent,
                        }}
                        key={index}
                        onClick={() => setSendAutoMessage(ele)}
                      >
                        {ele}
                      </p>
                    );
                  })}
                </div>
              </div>
            ) : (
              ""
            )}

